package com.genymobile.scrcpy;

/**
 * scrcpy-ez 通知大图标数据：512x512 白底 PNG（显示器 + 手机品牌插画）的 base64。
 *
 * 背景：scrcpy-server 以 shell(uid 2000) 身份在 app_process 里运行，没有自己的资源包，
 * 不能用 R.drawable；通知左侧图标位原先显示 com.android.shell 的系统默认图标。
 * 这里把处理好的品牌 PNG 以 base64 内嵌（构建产物无外部文件依赖），运行时
 * BitmapFactory.decodeByteArray 解出 Bitmap 交给 Notification.Builder.setLargeIcon。
 *
 * 原始素材：D:/dsh_work/icon_source.png（256x256，含绿色圆角外框）。
 * 处理：去绿框（连通域 + 邻域刷白，白底保留、插画与四角星点零改动）后放大到 512x512。
 * 数据分段存放：单个字符串常量有 64KB UTF-8 上限，故按 20000 字符切块，运行时拼接。
 */
public final class NotificationIconData {

    /** PNG base64 分段（每段 20000 字符，均小于 Java 单常量 64KB 上限）。 */
    private static final String[] CHUNKS = {
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    };

    private NotificationIconData() {
        // not instantiable
    }

    /** 拼接出完整 base64（9 段，共 161216 字符）。 */
    public static String base64() {
        StringBuilder sb = new StringBuilder(161232);
        for (String chunk : CHUNKS) {
            sb.append(chunk);
        }
        return sb.toString();
    }
}
